"use strict";
const{test}=require("node:test"),S=require("./support.cjs"),{assert}=S;
test("shared participant rejects before local staging or shared preparation",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f));q.participant="shared-project-data";const before=await S.fs.readFile(f.file,"utf8"),files=await S.fs.readdir(f.directory);assert.equal((await f.store.transact(q)).status,"unsupported-participant");assert.equal(await S.fs.readFile(f.file,"utf8"),before);assert.deepEqual(await S.fs.readdir(f.directory),files);});
test("updated legacy blind/raw writers refuse recognized managed files",async t=>{const f=await S.fixture(t),plugin={app:{vault:{adapter:{getBasePath:()=>f.directory},configDir:".obsidian"}},manifest:{dir:f.directory},saveData:async()=>assert.fail("fallback")},old=new S.api.HubDataStore(plugin);await assert.rejects(old.save({folderUi:{}}),{code:"MANAGED_TRANSACTIONS_REQUIRED"});await assert.rejects(old.atomicWrite({},f.file),{code:"MANAGED_TRANSACTIONS_REQUIRED"});assert.equal((await S.disk(f)).revision,0);});
test("frozen old loader refuses marker but frozen blind writer remains incompatible",async t=>{const f=await S.fixture(t);await f.store.close();const plugin={app:{vault:{adapter:{getBasePath:()=>f.directory},configDir:".obsidian"}},manifest:{dir:f.directory},loadData:()=>S.disk(f)},Frozen=S.frozen().HubDataStore,old=new Frozen(plugin);await assert.rejects(old.load(),/newer/);await new Frozen(plugin).save({folderUi:{old:true}});assert.equal((await S.disk(f)).hubState.schemaVersion,1);});
